function isRoundTrip(encode, decode, x) {
  return JSON.stringify(decode(encode(x))) === JSON.stringify(x);
}

function isIdempotent(fn, x) {
  return JSON.stringify(fn(fn(x))) === JSON.stringify(fn(x));
}

function keepsLength(fn, list) {
  return fn(list).length === list.length;
}

function isSortedAscending(list) {
  for (let i = 1; i < list.length; i++) {
    if (list[i - 1] > list[i]) return false;
  }
  return true;
}

function hasNoDuplicates(list) {
  return new Set(list).size === list.length;
}

function sameElements(a, b) {
  const sa = [...a].sort((x, y) => x - y);
  const sb = [...b].sort((x, y) => x - y);
  return JSON.stringify(sa) === JSON.stringify(sb);
}

function matchesOracle(mySort, list) {
  const expected = [...list].sort((a, b) => a - b);
  return JSON.stringify(mySort([...list])) === JSON.stringify(expected);
}

function neverIncreases(applyDiscount, price, code) {
  return applyDiscount(price, code) <= price;
}

function isSortedAndNonOverlapping(intervals) {
  for (let i = 1; i < intervals.length; i++) {
    if (intervals[i].start <= intervals[i - 1].end) return false;
  }
  return true;
}

function coversSamePoints(input, output) {
  const points = (list) => {
    const s = new Set();
    for (const { start, end } of list) {
      for (let i = start; i <= end; i++) s.add(i);
    }
    return s;
  };
  const a = points(input);
  const b = points(output);
  if (a.size !== b.size) return false;
  for (const x of a) if (!b.has(x)) return false;
  return true;
}

function firstFailingInput(property, inputs) {
  for (const input of inputs) {
    if (!property(input)) return input;
  }
  return null;
}

function shrinkOnce(items, stillFails) {
  for (let i = 0; i < items.length; i++) {
    const smaller = items.filter((_, idx) => idx !== i);
    if (smaller.length > 0 && stillFails(smaller)) return smaller;
  }
  return items;
}
